def has_close_elements(numbers: list[float], threshold: float) -> bool:
    for idx, elem in enumerate(numbers):
        for idx2, elem2 in enumerate(numbers):
            if idx != idx2:
                distance = abs(elem - elem2)
                if distance < threshold:
                    return True
    return False

assert has_close_elements([1.0, 2.0, 3.9, 4.0, 5.0], 0.2) == True
assert has_close_elements([1.0, 2.0, 3.9, 4.0, 5.0], 0.05) == False
assert has_close_elements([1.0, 2.8, 3.0, 4.0, 5.0], 0.3) == True

def truncate_number(number: float) -> float:
    return round(number - int(number), 4)

assert truncate_number(3.5) == 0.5
assert truncate_number(1.33) == 0.33

def below_zero(operations: list[int]) -> bool:
    balance = 0
    for op in operations:
        balance += op
        if balance < 0:
            return True
    return False

assert below_zero([1, 2, 3]) == False
assert below_zero([1, 2, -4, 5]) == True
assert below_zero([1, -1, 2, -2, 5, -6]) == True

def intersperse(numbers: list[int], delimiter: int) -> list[int]:
    if not numbers:
        return []
    res = [numbers[0]]
    for n in numbers[1:]:
        res.extend([delimiter, n])
    return res

assert intersperse([], 4) == []
assert intersperse([1, 2, 3], 4) == [1, 4, 2, 4, 3]

def parse_nested_parens(paren_string: str) -> list[int]:
    def get_max_depth(group: str) -> int:
        max_d = 0
        cur_d = 0
        for c in group:
            if c == '(':
                cur_d += 1
                max_d = max(max_d, cur_d)
            elif c == ')':
                cur_d -= 1
        return max_d
    return [get_max_depth(g) for g in paren_string.split() if g]

assert parse_nested_parens('(()()) ((())) () ((())()())') == [2, 3, 1, 3]

